<?php $labels=['late'=>'遅刻','early'=>'早退','leave_full'=>'有給休暇（1日）','leave_am'=>'有給休暇（午前休）','leave_pm'=>'有給休暇（午後休）','absence'=>'欠勤','holiday_work'=>'休日出勤','medical'=>'健康診断','other'=>'その他']; ?>
<div class="page-head"><div><h1>勤怠連絡</h1><p class="muted">遅刻・早退・欠勤などを登録します。</p></div></div>
<div class="two-col form-first"><section class="panel"><h2>新しい連絡</h2><form method="post" action="<?= e(url('notice/create')) ?>"><?= \App\Csrf::field() ?><label>対象日<input type="date" name="target_date" required></label><label>勤怠種別<select name="notice_type" required><?php foreach($labels as $value=>$label): ?><option value="<?= e($value) ?>"><?= e($label) ?></option><?php endforeach; ?></select></label><div class="field-row"><label>出勤見込み<input type="time" name="expected_start"></label><label>退勤見込み<input type="time" name="expected_end"></label></div><label>事前確認相手（有給の場合）<input name="confirmed_with"></label><label>連絡内容・理由<textarea name="details" rows="4"></textarea></label><button class="primary">登録する</button></form></section>
<section class="panel"><h2>登録履歴</h2><div class="table-wrap"><table><thead><tr><th>対象日</th><th>種別</th><th>内容</th></tr></thead><tbody><?php foreach($notices as $notice): ?><tr><td><?= e($notice['target_date']) ?></td><td><?= e($labels[$notice['notice_type']]) ?></td><td><?= nl2br(e($notice['details'])) ?></td></tr><?php endforeach; ?><?php if(!$notices): ?><tr><td colspan="3" class="empty">履歴はありません。</td></tr><?php endif; ?></tbody></table></div></section></div>

